import React from 'react';

import { useNavigate, useSearchParams } from 'react-router-dom';

import { getSQLDate } from '@helpers/dateHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import ActivitiesMap from './ActivitiesMap';
import ActivitiesYearChart from './ActivitiesYearChart';
import WorkoutsListStatistic from './WorkoutsListStatistic';
import { getWorkouts } from '../@services/workouts.service';
import { IWorkout } from '../@types/workouts.types';
import WorkoutListItem from '../WorkoutListItem';
import WorkoutListGroup from '../WorkoutListItem/WorkoutListGroup';

interface IWorkoutsListProps {
  batchSize?: number;

  id_group?: number;
  id_user?: number;
  d1?: string;
  d2?: string;
  tag?: string;
  withTracks?: boolean;
}

const WorkoutsList: React.FC<IWorkoutsListProps> = ({
  batchSize = 50,
  id_group,
  id_user,
  d1,
  d2,
  withTracks,
}) => {
  const [page, setPage] = React.useState(0);
  const [loading, setLoading] = React.useState(true);
  const [lastBatchSize, setLastBatchSize] = React.useState(batchSize);
  const [data, setData] = React.useState<Array<IWorkout | IWorkout[]>>([]);
  const [err, setErr] = React.useState<Error | null>(null);

  const [searchParams, setSearchParams] = useSearchParams();

  const navigate = useNavigate();

  React.useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      const dt = await getWorkouts({
        offset: page * batchSize,
        limit: batchSize,
        id_group,
        id_user,
        d1: d1 ?? searchParams.get('d1') ?? undefined,
        d2: d2 ?? searchParams.get('d2') ?? undefined,
        tag: searchParams.get('tag') ?? undefined,
        d: searchParams.get('d') ?? undefined,
        y: searchParams.get('y') ?? undefined,
        type: searchParams.get('type') ?? undefined,
        ...(withTracks ? { include_trackdata: 1 } : {}),
      });
      setLastBatchSize(dt.length);
      setData((c) => {
        const fullNewArray = c.concat(dt);
        fullNewArray.forEach(() => {});

        const res: Array<IWorkout | IWorkout[]> = [];

        fullNewArray.forEach((d) => {
          if (Array.isArray(d) || !d.group?.id) {
            res.push(d);
            return;
          }
          const indexOfGroup = res.findIndex(
            (r) => Array.isArray(r) && r[0].group?.id === d.group?.id,
          );
          if (indexOfGroup > -1) {
            (res[indexOfGroup] as IWorkout[]).push(d);
            return undefined;
          } else {
            res.push([d]);
          }
        });

        return res;
      });
    };

    fetchData()
      .catch(setErr)
      .finally(() => setLoading(false));
  }, [
    page,
    searchParams.get('y'),
    searchParams.get('d'),
    searchParams.get('tag'),
    searchParams.get('type'),
  ]);

  React.useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY + window.innerHeight >= document.documentElement.scrollHeight) {
        !loading && lastBatchSize === batchSize && setPage((c) => c + 1);
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [page, lastBatchSize, loading]);

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  const withChart = batchSize > 50;
  const withSummary = batchSize > 50;

  const isMultiCol = withChart || withSummary || withTracks;

  return (
    <PohRow>
      {isMultiCol && (
        <PohCol sm="12">
          {withSummary && <WorkoutsListStatistic data={data} />}
          {withChart && data.length > 0 && (
            <ActivitiesYearChart
              d1={searchParams.has('d1') ? new Date(searchParams.get('d1')!) : undefined}
              d2={searchParams.has('d2') ? new Date(searchParams.get('d2')!) : undefined}
              activities={data.map((val) => (Array.isArray(val) ? val[0] : val)) as IWorkout[]}
              onDateClick={(d) => {
                setData([]);
                searchParams.set('d', getSQLDate(d).substring(0, 10));
                setSearchParams(searchParams, { replace: true });
                setLastBatchSize(batchSize);
              }}
            />
          )}

          {withTracks && (
            <ActivitiesMap
              activities={data.map((val) => (Array.isArray(val) ? val[0] : val)) as IWorkout[]}
              style={{ height: 400 }}
              onTrackClick={(w) => navigate(`/workouts/${w.id}`)}
              className="mb-2"
            />
          )}
        </PohCol>
      )}

      <PohCol sm={12}>
        <PohList
          data={data.map((d) => ({
            key: Array.isArray(d) ? d[0].id : d.id,
            content: Array.isArray(d) ? (
              <WorkoutListGroup workouts={d} />
            ) : (
              <WorkoutListItem data={d} />
            ),
            action: true,
            onClick: () =>
              navigate(
                Array.isArray(d) ? `/workouts/group/${d[0].group?.id}` : `/workouts/${d.id}`,
              ),
          }))}
        />
        {loading && (
          <div className="text-center text-muted p-4">
            <PohLoader /> Загрузка...
          </div>
        )}
      </PohCol>
    </PohRow>
  );
};

export default WorkoutsList;
